export default function GuidePage() {
  const pathname = useLocation().pathname.replace(/\/$/, "");
  if (pathname === "/ai-beta-reader") return <AIBetaReaderPage />;
  const guide = content.guides[pathname];
  const relatedGuides = [
    ["/beta-readers", "A practical guide to beta readers"],
    ["/ai-beta-reader", "How AI beta readers work"],
    ["/manuscript-feedback", "Working with manuscript feedback"],
  ].filter(([path]) => path !== pathname);
  return <><SiteHeader /><main id="main-content" className="search-guide page-width" tabIndex={-1}><nav aria-label="Breadcrumb"><Link to="/">Readerfold</Link> / Writing resources</nav><h1>{guide.heading}</h1><p className="guide-intro">{guide.intro}</p>{guide.sections.map(section => <section key={section.heading}><h2>{section.heading}</h2><p>{section.text}</p></section>)}<section><h2>Put the feedback to work</h2><p>Use the <a href="/guides/beta-reader-questionnaire/">free beta reader questionnaire</a> to ask for specific reactions, then compare conflicting notes with the <a href="/guides/conflicting-beta-reader-feedback/">feedback decision worksheet</a>. Both include examples and editable downloads.</p></section><Link to="/signup" className="button button-primary">Try a reading with your draft</Link><p>Written by the Readerfold team. AI feedback supports your judgment; it does not guarantee publication or reader response.</p><nav aria-label="Related resources"><Link to="/use-cases/">Worked revision examples</Link> · <Link to="/sample-reading/">Explore an annotated sample reading</Link>{relatedGuides.map(([path, label]) => <React.Fragment key={path}> · <Link to={`${path}/`}>{label}</Link></React.Fragment>)} · <Link to="/pricing/">Plans and credits</Link></nav></main><ProductFAQ /><SiteFooter /></>;
}
